from datetime import datetime

class Chat:
    TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"

    def __init__(self):
        self._users = {}

    @property
    def users(self):
        return dict(self._users)

    @users.setter
    def users(self, value):
        if value is None:
            self._users = {}
        else:
            self._users = dict(value)

    def add_user(self, username):
        if self._is_user_registered(username):
            return False
        self._register_user(username)
        return True

    def _is_user_registered(self, username):
        return username in self._users

    def _register_user(self, username):
        self._users[username] = []

    def remove_user(self, username):
        if self._is_user_registered(username):
            self._remove_user_entry(username)
            return True
        return False

    def _remove_user_entry(self, username):
        del self._users[username]

    def send_message(self, sender, receiver, message):
        if not self._can_send_message(sender, receiver):
            return False
        self._deliver_message(sender, receiver, message)
        return True

    def _can_send_message(self, sender, receiver):
        return self._is_user_registered(sender) and self._is_user_registered(receiver)

    def _deliver_message(self, sender, receiver, message):
        timestamp = self._get_current_timestamp()
        message_info = self._build_message(sender, receiver, message, timestamp)
        self._add_message_to_user(sender, message_info)
        self._add_message_to_user(receiver, message_info)

    def _get_current_timestamp(self):
        return datetime.now().strftime(self.TIMESTAMP_FORMAT)

    def _build_message(self, sender, receiver, message, timestamp):
        return {
            'sender': sender,
            'receiver': receiver,
            'message': message,
            'timestamp': timestamp
        }

    def _add_message_to_user(self, username, message_info):
        self._users[username].append(message_info)

    def get_messages(self, username):
        if not self._is_user_registered(username):
            return []
        return list(self._users[username])
